"use client"

import * as React from "react"
import { cn } from "@/lib/utils"

export type AnimeEase =
  | "outQuad"
  | "outCubic"
  | "outExpo"
  | "inOutQuad"
  | "inOutCubic"
  | "inOutExpo"
  | "linear"
  | "spring"

export interface AnimeLayoutStateParams {
  transform?: string
  opacity?: number
  scale?: number
  duration?: number
  ease?: AnimeEase
  delay?: number | ((index: number, total: number) => number)
}

export interface AnimeLayoutSettings {
  children?: string
  duration?: number
  delay?: number | ((index: number, total: number) => number)
  ease?: AnimeEase
  properties?: string[]
  enterFrom?: AnimeLayoutStateParams
  leaveTo?: AnimeLayoutStateParams
  swapAt?: AnimeLayoutStateParams
  onBegin?: () => void
  onUpdate?: () => void
  onComplete?: () => void
}

export interface AnimeLayoutInstance {
  root: HTMLElement
  record: () => void
  animate: (options?: AnimeLayoutSettings) => Animation[]
  update: (
    callback: (context: { root: HTMLElement }) => void,
    options?: AnimeLayoutSettings
  ) => Promise<void>
  revert: () => void
  destroy: () => void
}

const EASE_MAP: Record<AnimeEase, string> = {
  outQuad: "cubic-bezier(0.25, 0.46, 0.45, 0.94)",
  outCubic: "cubic-bezier(0.215, 0.61, 0.355, 1)",
  outExpo: "cubic-bezier(0.19, 1, 0.22, 1)",
  inOutQuad: "cubic-bezier(0.455, 0.03, 0.515, 0.955)",
  inOutCubic: "cubic-bezier(0.645, 0.045, 0.355, 1)",
  inOutExpo: "cubic-bezier(1, 0, 0, 1)",
  linear: "linear",
  spring: "cubic-bezier(0.175, 0.885, 0.32, 1.275)",
}

export function stagger(
  value: number,
  options?: { from?: "first" | "last" | "center"; start?: number }
) {
  const from = options?.from ?? "first"
  const start = options?.start ?? 0

  return (index: number, total: number) => {
    let position = index
    if (from === "last") {
      position = total - 1 - index
    } else if (from === "center") {
      const center = (total - 1) / 2
      position = Math.abs(center - index)
    }
    return start + position * value
  }
}

export function createLayout(
  rootTarget: HTMLElement | string,
  parameters: AnimeLayoutSettings = {}
): AnimeLayoutInstance | null {
  if (typeof window === "undefined") return null

  const root =
    typeof rootTarget === "string"
      ? (document.querySelector<HTMLElement>(rootTarget) ?? null)
      : rootTarget

  if (!root) return null

  const config: AnimeLayoutSettings = {
    duration: 350,
    delay: 0,
    ease: "outExpo",
    children: ".item, [data-layout-id]",
    enterFrom: { opacity: 0, transform: "scale(0.85)" },
    leaveTo: { opacity: 0, transform: "scale(0.85)" },
    ...parameters,
  }

  const snapshotMap = new Map<
    string | Element,
    { rect: DOMRect; opacity: number; transform: string }
  >()
  let activeAnimations: Animation[] = []

  function getElements(): HTMLElement[] {
    const selector = config.children ?? ".item, [data-layout-id]"
    return Array.from(root!.querySelectorAll<HTMLElement>(selector))
  }

  function record() {
    snapshotMap.clear()
    const elements = getElements()

    for (const el of elements) {
      const id = el.dataset.layoutId || el
      const rect = el.getBoundingClientRect()
      const style = window.getComputedStyle(el)
      snapshotMap.set(id, {
        rect,
        opacity: Number.parseFloat(style.opacity) || 1,
        transform: style.transform,
      })
    }
  }

  function animate(overrideOptions?: AnimeLayoutSettings): Animation[] {
    const currentConfig = { ...config, ...overrideOptions }
    const elements = getElements()
    const newAnimations: Animation[] = []
    const total = elements.length

    // stop existing animations
    for (const anim of activeAnimations) {
      anim.cancel()
    }
    activeAnimations = []

    currentConfig.onBegin?.()

    elements.forEach((el, index) => {
      const id = el.dataset.layoutId || el
      const prev = snapshotMap.get(id)
      const currentRect = el.getBoundingClientRect()

      const duration =
        typeof currentConfig.duration === "function"
          ? currentConfig.duration
          : (currentConfig.duration ?? 350)

      let delay = 0
      if (typeof currentConfig.delay === "function") {
        delay = currentConfig.delay(index, total)
      } else if (typeof currentConfig.delay === "number") {
        delay = currentConfig.delay
      }

      const easing = EASE_MAP[currentConfig.ease ?? "outExpo"] || EASE_MAP.outExpo

      if (!prev) {
        // Element is entering
        const enterOpacity = currentConfig.enterFrom?.opacity ?? 0
        const enterTransform =
          currentConfig.enterFrom?.transform ?? "scale(0.85)"

        const anim = el.animate(
          [
            { opacity: enterOpacity, transform: enterTransform },
            { opacity: 1, transform: "none" },
          ],
          {
            duration: currentConfig.enterFrom?.duration ?? duration,
            delay,
            easing:
              EASE_MAP[currentConfig.enterFrom?.ease ?? currentConfig.ease ?? "outExpo"] ||
              easing,
            fill: "both",
          }
        )
        newAnimations.push(anim)
        return
      }

      const deltaX = prev.rect.left - currentRect.left
      const deltaY = prev.rect.top - currentRect.top
      const deltaW = prev.rect.width / (currentRect.width || 1)
      const deltaH = prev.rect.height / (currentRect.height || 1)

      if (
        Math.abs(deltaX) > 0.5 ||
        Math.abs(deltaY) > 0.5 ||
        Math.abs(deltaW - 1) > 0.01 ||
        Math.abs(deltaH - 1) > 0.01
      ) {
        const anim = el.animate(
          [
            {
              transform: `translate(${deltaX}px, ${deltaY}px) scale(${deltaW}, ${deltaH})`,
              transformOrigin: "top left",
            },
            {
              transform: "none",
              transformOrigin: "top left",
            },
          ],
          {
            duration,
            delay,
            easing,
            fill: "both",
          }
        )
        newAnimations.push(anim)
      }
    })

    activeAnimations = newAnimations

    Promise.all(newAnimations.map((a) => a.finished.catch(() => {}))).then(() => {
      currentConfig.onComplete?.()
    })

    return newAnimations
  }

  async function update(
    callback: (context: { root: HTMLElement }) => void,
    overrideOptions?: AnimeLayoutSettings
  ): Promise<void> {
    record()
    callback({ root: root! })
    // force synchronous layout flush
    void root!.offsetHeight
    animate(overrideOptions)
  }

  function revert() {
    for (const anim of activeAnimations) {
      anim.cancel()
    }
    activeAnimations = []
  }

  function destroy() {
    revert()
    snapshotMap.clear()
  }

  return {
    root,
    record,
    animate,
    update,
    revert,
    destroy,
  }
}

export function useAnimeLayout(
  rootRef: React.RefObject<HTMLElement | null>,
  options?: AnimeLayoutSettings
) {
  const layoutRef = React.useRef<AnimeLayoutInstance | null>(null)

  React.useEffect(() => {
    if (!rootRef.current) return
    layoutRef.current = createLayout(rootRef.current, options)
    return () => {
      layoutRef.current?.destroy()
      layoutRef.current = null
    }
  }, [rootRef, options])

  const update = React.useCallback(
    (
      callback: (context: { root: HTMLElement }) => void,
      overrideOptions?: AnimeLayoutSettings
    ) => {
      return layoutRef.current?.update(callback, overrideOptions)
    },
    []
  )

  const record = React.useCallback(() => {
    layoutRef.current?.record()
  }, [])

  const animate = React.useCallback((overrideOptions?: AnimeLayoutSettings) => {
    return layoutRef.current?.animate(overrideOptions)
  }, [])

  return {
    layout: layoutRef,
    update,
    record,
    animate,
  }
}

export interface AnimeLayoutItem {
  id: string
  title: string
  subtitle?: string
  badge?: string
  color?: string
  icon?: React.ReactNode
}

export interface AnimeAutoLayoutProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "children"> {
  items?: AnimeLayoutItem[]
  layout?: "grid-4" | "grid-3" | "grid-2" | "flex-row" | "flex-col" | "bento"
  duration?: number
  ease?: AnimeEase
  staggerDelay?: number
  onItemClick?: (item: AnimeLayoutItem) => void
  children?: React.ReactNode
}

export function AnimeAutoLayout({
  items,
  layout = "grid-3",
  duration = 450,
  ease = "outExpo",
  staggerDelay = 40,
  onItemClick,
  className,
  children,
  ...props
}: AnimeAutoLayoutProps) {
  const containerRef = React.useRef<HTMLDivElement>(null)
  const layoutEngineRef = React.useRef<AnimeLayoutInstance | null>(null)

  React.useEffect(() => {
    if (!containerRef.current) return
    layoutEngineRef.current = createLayout(containerRef.current, {
      duration,
      ease,
      delay: stagger(staggerDelay),
      children: ".anime-layout-item, [data-layout-id]",
    })

    return () => {
      layoutEngineRef.current?.destroy()
      layoutEngineRef.current = null
    }
  }, [duration, ease, staggerDelay])

  const prevLayoutRef = React.useRef(layout)

  React.useEffect(() => {
    if (prevLayoutRef.current !== layout && layoutEngineRef.current) {
      prevLayoutRef.current = layout
      layoutEngineRef.current.record()
      // trigger animation on next frame after DOM reflow
      requestAnimationFrame(() => {
        layoutEngineRef.current?.animate({
          duration,
          ease,
          delay: stagger(staggerDelay),
        })
      })
    }
  }, [layout, duration, ease, staggerDelay])

  const layoutClasses = {
    "grid-4": "grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-3.5",
    "grid-3": "grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4",
    "grid-2": "grid grid-cols-1 sm:grid-cols-2 gap-4",
    "flex-row": "flex flex-row flex-wrap gap-3.5",
    "flex-col": "flex flex-col gap-2.5",
    bento: "grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4 [grid-auto-flow:dense]",
  }[layout]

  return (
    <div
      ref={containerRef}
      data-slot="anime-auto-layout"
      className={cn("w-full transition-all", layoutClasses, className)}
      {...props}
    >
      {children
        ? children
        : items?.map((item, index) => {
            const isBento = layout === "bento" && (index === 0 || index === 3)
            return (
              <div
                key={item.id}
                data-layout-id={item.id}
                onClick={() => onItemClick?.(item)}
                className={cn(
                  "anime-layout-item group relative overflow-hidden rounded-2xl border border-zinc-200/90 bg-white p-4 shadow-xs transition-colors hover:border-zinc-300 dark:border-zinc-800 dark:bg-zinc-900/90 dark:hover:border-zinc-700 cursor-pointer select-none",
                  isBento && "sm:col-span-2",
                  layout === "flex-col" ? "flex items-center justify-between py-3" : "flex flex-col justify-between min-h-[120px]"
                )}
              >
                <div className="flex items-center gap-3">
                  {item.icon ? (
                    <div
                      className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl text-white shadow-xs"
                      style={{ backgroundColor: item.color ?? "#10b981" }}
                    >
                      {item.icon}
                    </div>
                  ) : null}
                  <div>
                    <h4 className="font-semibold text-sm tracking-tight text-zinc-900 dark:text-white">
                      {item.title}
                    </h4>
                    {item.subtitle ? (
                      <p className="text-xs text-zinc-500 dark:text-zinc-400">
                        {item.subtitle}
                      </p>
                    ) : null}
                  </div>
                </div>

                {item.badge ? (
                  <span className="rounded-full bg-zinc-100 px-2.5 py-0.5 text-[11px] font-medium text-zinc-600 dark:bg-zinc-800 dark:text-zinc-300 shrink-0">
                    {item.badge}
                  </span>
                ) : null}
              </div>
            )
          })}
    </div>
  )
}
